rap gap-2"><a class="btn btn-sm btn-outline-primary" href="<?= e(app_url('src/dashboard/companies/form.php').'?id='.(int)$company['id']) ?>">Editar</a><?php if($company['estado']==='activa'&&!$isActive): ?><form method="post" action="<?= e(app_url('src/dashboard/companies/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$company['id'] ?>"><input type="hidden" name="action" value="activate"><button class="btn btn-sm btn-primary text-white" type="submit">Activar</button></form><?php endif; ?><?php if($company['estado']==='activa'): ?><form method="post" action="<?= e(app_url('src/dashboard/companies/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$company['id'] ?>"><input type="hidden" name="action" value="deactivate"><button class="btn btn-sm btn-outline-secondary" type="submit">Desactivar</button></form><?php elseif($company['estado']==='inactiva'): ?><form method="post" action="<?= e(app_url('src/dashboard/companies/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$company['id'] ?>"><input type="hidden" name="action" value="enable"><button class="btn btn-sm btn-outline-success" type="submit">Habilitar</button></form><?php endif; ?><?php if($currentUser['rol']==='administrador'&&$company['estado']!=='bloqueada'): ?><form method="post" action="<?= e(app_url('src/dashboard/companies/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$company['id'] ?>"><input type="hidden" name="action" value="block"><button class="btn btn-sm btn-outline-danger" type="submit">Bloquear</button></form><?php endif; ?></div></div></article></div><?php endforeach; ?></div><?php endif; ?>
